);
COMMENT ON TABLE dam_standard.data_standard IS '数据标准库表—— 数据标准库（命名/编码/类型/枚举/度量规则标准，融合自现平台）';
CREATE TABLE IF NOT EXISTS dam_standard.standard_code_table (
    id             bigserial PRIMARY KEY,
