CREATE TABLE IF NOT EXISTS hospital_demo.biz_aux_exam (
    id             bigserial PRIMARY KEY,
    exam_no        varchar(32) NOT NULL,
    encounter_no   varchar(32) NOT NULL,
    patient_id     varchar(32) NOT NULL,
    exam_type      varchar(16) NOT NULL,
