SELECT (select id from dam_sys.sys_role where role_code='STEWARD'), p.id, 'seeder'
FROM dam_sys.sys_permission p WHERE p.permission_code IN ('metadata:sync','quality:run');

-- 平台自身九大模块已按模块拆分 schema（dam_sys/dam_metadata/dam_asset/dam_model/dam_security/dam_standard/dam_ticket/dam_service/dam_sched），不再登记单一 'dam' schema

SELECT ds.id, sc.id, c.relname, coalesce(obj_description(c.oid),''), 'TABLE',
       greatest(c.reltuples,0)::bigint::text, pg_total_relation_size(c.oid)::text, now(), now(), now(), 'seeder'
FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
JOIN dam_metadata.metadata_datasource ds ON ds.ds_code='DS-LOCAL-DEMO'
JOIN dam_metadata.metadata_schema sc ON sc.datasource_id=ds.id AND sc.schema_name='hospital_demo'
WHERE n.nspname='hospital_demo' AND c.relkind='r';
SELECT ds.id, sc.id, t.tname, t.tcomment, 'TABLE', '0', '0', now(), now(), now(), 'seeder'
FROM (VALUES ('PA_PatMas','患者主索引表'),('PA_Adm','就诊登记表'),('OE_Order','医嘱表'),('OE_OrdItem','医嘱项目明细'),
 ('OE_OrdExec','医嘱执行表'),('MR_Adm','病历首页'),('MR_Diagnose','病历诊断'),('MRC_ICDDx','ICD 诊断字典'),
 ('CT_Sex','性别字典'),('CT_Nation','民族字典'),('CT_Loc','科室字典'),('CT_Marital','婚姻字典'),
 ('CT_CareProv','职工字典'),('CIS_Model.OperSchedule','手术排程')) AS t(tname,tcomment)
JOIN dam_metadata.metadata_datasource ds ON ds.ds_code='DS-IRIS'
JOIN dam_metadata.metadata_schema sc ON sc.datasource_id=ds.id AND sc.schema_name='PROD';
SELECT ds.id, sc.id, t.id, a.attname, format_type(a.atttypid, a.atttypmod), NOT a.attnotnull,
       (a.attname='id'), a.attnum, coalesce(col_description(a.attrelid, a.attnum),''), 'seeder'
FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
JOIN dam_metadata.metadata_datasource ds ON ds.ds_code='DS-LOCAL-DEMO'
JOIN dam_metadata.metadata_schema sc ON sc.datasource_id=ds.id AND sc.schema_name='hospital_demo'
JOIN dam_metadata.metadata_table t ON t.table_name=c.relname AND t.schema_id=sc.id
WHERE n.nspname='hospital_demo' AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped;
ANALYZE hospital_demo.biz_patient_master, hospital_demo.biz_encounter, hospital_demo.biz_diagnosis;











