INSERT INTO dam_service.api_service (api_code, name, asset_id, sql_text, params_json, approval_status, approved_by, approved_at, rate_limit, quota_day, owner, description, created_by) VALUES ('API-PATIENT-360', '患者360全息查询', (select id from dam_asset.asset_info where asset_code='AST-0001'), 'select id, patient_id, patient_name, gender_code, birth_date, id_card, marital_status, nation, occupation from hospital_demo.biz_patient_master where patient_id = :patientId', '[{"name":"patientId","type":"string","required":true,"desc":"患者EMPI","example":"EMPI000001"}]', 'APPROVED', 'admin', '2026-10-24 02:10:00', 60, 10000, '张明', '患者主索引查询，身份证/姓名按安全策略脱敏返回', 'seeder');
INSERT INTO dam_service.api_service (api_code, name, asset_id, sql_text, params_json, approval_status, approved_by, approved_at, rate_limit, quota_day, owner, description, created_by) VALUES ('API-PATIENT-LIST', '患者列表检索', (select id from dam_asset.asset_info where asset_code='AST-0001'), 'select id, patient_id, patient_name, gender_code, birth_date from hospital_demo.biz_patient_master where (:keyword is null or patient_name like ''%''||:keyword||''%'') order by id limit 20', '[{"name":"keyword","type":"string","required":false,"desc":"姓名关键字","example":"王"}]', 'APPROVED', 'admin', '2026-10-24 02:10:00', 30, 5000, '张明', '按姓名模糊检索，最多 20 行', 'seeder');
INSERT INTO dam_service.api_service (api_code, name, asset_id, sql_text, params_json, approval_status, approved_by, approved_at, rate_limit, quota_day, owner, description, created_by) VALUES ('API-DEPT-STAT', '科室就诊统计', (select id from dam_asset.asset_info where asset_code='AST-0002'), 'select dept_code, dept_name, encounter_type, count(*) as cnt from hospital_demo.biz_encounter group by dept_code, dept_name, encounter_type order by cnt desc', NULL, 'APPROVED', 'admin', '2026-10-24 02:10:00', 60, 20000, '张明', '按科室×就诊类型聚合，非敏感接口', 'seeder');
INSERT INTO dam_service.api_service (api_code, name, asset_id, sql_text, params_json, approval_status, rate_limit, quota_day, owner, description, created_by) VALUES ('API-DIAG-QRY', '诊断记录查询', (select id from dam_asset.asset_info where asset_code='AST-0003'), 'select encounter_no, diagnosis_icd, diagnosis_name, diagnosis_type, is_primary, diagnosis_time from hospital_demo.biz_diagnosis where patient_id = :patientId order by diagnosis_time desc limit 50', '[{"name":"patientId","type":"string","required":true,"desc":"患者EMPI","example":"EMPI000001"}]', 'PENDING', 30, 5000, '张明', '患者历史诊断（待审批）', 'seeder');
